transforms.code:
# Always-loaded recurring series, anchored ~a month back so they page both ways.
d0 = system.date.midnight(value)
def at(n, h, m=0):
	return system.date.addMinutes(system.date.addHours(system.date.addDays(d0, n), h), m)
def iso(d):
	return system.date.format(d, "yyyy-MM-dd'T'HH:mm:ss")
return [
	{"id": "rec-walkdown", "title": "Morning walkdown", "start": iso(at(-30, 7)),
	"end": iso(at(-30, 7, 15)), "category": "ops",
	"description": "Recurring daily - drag or edit one occurrence to detach it.",
	"rrule": {"freq": "daily"}},
	{"id": "rec-toolbox", "title": "Toolbox talk", "start": iso(at(-35, 6, 30)),
	"end": iso(at(-35, 6, 45)), "category": "meeting",
	"description": "Recurring Mon/Wed/Fri.",
	"rrule": {"freq": "weekly", "byweekday": [1, 3, 5]}},
]

config.script:
# One handler for every mutation: create / edit / delete / move / resize,
# including recurring scope (series vs single occurrence), across BOTH
# data.events and the always-loaded data.recurringEvents.
ev = event.event
action = event.action
scope = getattr(event, "scope", None)            # 'series' | 'occurrence' | None
seriesId = getattr(event, "seriesId", None)
occDate = getattr(event, "occurrenceDate", None)
events = [dict(e) for e in self.props.data.events]
recurring = [dict(e) for e in self.props.data.recurringEvents]

def idx_of(lst, eid):
	for i in range(len(lst)):
		if lst[i].get("id") == eid:
			return i
	return -1

def row_from(e):
	row = {"id": e.id, "title": getattr(e, "title", ""), "start": getattr(e, "start", ""),
		"end": getattr(e, "end", ""), "allDay": getattr(e, "allDay", False),
		"category": getattr(e, "category", ""), "description": getattr(e, "description", "")}
	for k in ("color", "status", "display"):
		val = getattr(e, k, "")
		if val:
			row[k] = val
	rr = getattr(e, "rrule", None)
	if rr is not None:
		row["rrule"] = rr
	return row

def upsert(lst, row, merge=False):
	i = idx_of(lst, row.get("id"))
	if i >= 0:
		if merge:
			kept = dict(lst[i])
			kept.update(row)
			lst[i] = kept
		else:
			lst[i] = row
	else:
		lst.append(row)

def add_exdate(sid, d):
	# The series may live in data.events or data.recurringEvents.
	for lst in (events, recurring):
		i = idx_of(lst, sid)
		if i >= 0:
			base = dict(lst[i])
			rr = dict(base.get("rrule") or {})
			ex = list(rr.get("exdate") or [])
			if d not in ex:
				ex.append(d)
			rr["exdate"] = ex
			base["rrule"] = rr
			lst[i] = base
			return

if scope == "occurrence":
	add_exdate(seriesId, occDate)          # hide this date in the series
	if action == "delete":
		events = [e for e in events if e.get("id") != ev.id]
	else:
		upsert(events, row_from(ev))       # standalone override for this date
elif scope == "series":
	if action == "delete":
		events = [e for e in events if e.get("id") != seriesId]
		recurring = [e for e in recurring if e.get("id") != seriesId]
	else:
		if idx_of(recurring, seriesId) >= 0:
			upsert(recurring, row_from(ev))
		else:
			upsert(events, row_from(ev))
else:
	if action == "delete":
		events = [e for e in events if e.get("id") != ev.id]
	else:
		# merge keeps fields an older payload might not carry
		upsert(events, row_from(ev), merge=True)

self.props.data.events = events
self.props.data.recurringEvents = recurring

onChange.script:
val = currentValue.value if currentValue else None
if val and val != self.session.props.theme:
	self.session.props.theme = val
